import {chromium, expect} from '../../node_modules/@playwright/test/index.mjs';
import {controlledTransport, emit, state, run, domain} from '../../tests/browser/transport.js';
import {pathToFileURL} from 'node:url';
import {mkdir,writeFile,readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const out='.scratch/v03/captures';await mkdir(out,{recursive:true});
const browser=await chromium.launch();
const report={browser:browser.version(),port:18030,deviceScaleFactor:1,viewports:[],reference:[],checks:{},errors:[],requests:[]};
const write=async(name,value)=>writeFile(out+'/'+name,JSON.stringify(value,null,2)+'\n');
const measure=async(page,reference=false)=>page.evaluate(reference=>{
  const box=node=>node?.getBoundingClientRect().toJSON();
  const css=node=>{if(!node)return null;const s=getComputedStyle(node);return Object.fromEntries(['fontFamily','fontSize','lineHeight','backgroundColor','borderColor','borderStyle','borderRadius','maxWidth','animationName','padding'].map(key=>[key,s[key]]));};
  const root=document.querySelector(reference?'aside':'#mainbar');
  return {root:box(root),main:box(document.querySelector('main')),documentOverflow:document.documentElement.scrollWidth-innerWidth,rootOverflow:root.scrollWidth-root.clientWidth,inlineStyles:document.querySelectorAll('[style]').length,user:css(document.querySelector(reference?'aside>div:nth-child(2)>div':'#messages .message-user')),assistant:css(document.querySelector(reference?'aside>div:nth-child(2)>div:nth-child(2)>div':'#messages .message-assistant')),composer:css(document.querySelector(reference?'aside input':'#message')),dot:css(document.querySelector('#mainbar-dot')),stage:document.querySelector('#mainbar-stage')?.textContent,conversation:box(document.querySelector('#conversation')),bubbles:[...document.querySelectorAll('#messages .message-bubble')].map(node=>({class:node.className,text:node.textContent,box:box(node),overflow:node.scrollWidth-node.clientWidth})),messageStructure:[...document.querySelectorAll('#messages article')].map(node=>({run:node.dataset.runId,children:[...node.children].map(child=>({tag:child.tagName,class:child.className,text:child.textContent,href:child.getAttribute('href')}))}))};
},reference);
try {
  const context=await browser.newContext({viewport:{width:1440,height:900},deviceScaleFactor:1,reducedMotion:'reduce'});
  const page=await context.newPage();
  page.on('pageerror',error=>report.errors.push({kind:'pageerror',message:String(error)}));
  page.on('requestfailed',request=>report.errors.push({kind:'requestfailed',url:request.url(),failure:request.failure()}));
  page.on('request',request=>report.requests.push({method:request.method(),url:request.url()}));
  await page.goto('http://127.0.0.1:18030/overview');
  await expect(page.getByRole('heading',{name:'总览',exact:true})).toBeVisible();
  await writeFile(out+'/alfred-initial-aria.txt',await page.locator('body').ariaSnapshot());
  await page.getByRole('button',{name:'新建会话',exact:true}).click();
  const input=page.getByRole('textbox',{name:'消息',exact:true});
  const ids=[];
  for(const text of ['请检查主对话的正式回复、保存状态和运行入口。','长消息换行验证：中文正文仍然完整可读。\n/very-long-path/'+('mainbar-message-'.repeat(9))+'\n这个请求包含换行；状态文字和草稿继续保留。']){
    await input.fill(text);await expect(page.getByRole('button',{name:'发送',exact:true})).toBeEnabled();
    const response=page.waitForResponse(response=>response.url().endsWith('/api/runs')&&response.request().method()==='POST');
    await page.getByRole('button',{name:'发送',exact:true}).click();const accepted=await response;expect(accepted.status()).toBe(202);
    const {run_id}=await accepted.json();ids.push(run_id);
    await expect(page.locator('#messages [data-run-id="'+run_id+'"]')).toContainText('已保存');
  }
  await input.fill('这份未发送草稿在四个视口里保持不变。');
  report.session=await page.evaluate(()=>sessionStorage.getItem('alfred.session'));report.runs=ids;
  for(const [width,height] of [[1440,900],[1280,800],[390,844],[320,800]]){
    await page.setViewportSize({width,height});
    if(width<1100 && !await page.locator('#mainbar').isVisible())await page.locator('#shell-toolbar [data-open-panel="mainbar"]').click();
    await expect(page.locator('#mainbar')).toBeVisible();
    await expect(input).toHaveValue('这份未发送草稿在四个视口里保持不变。');
    await page.locator('#conversation').evaluate(node=>node.scrollTop=node.scrollHeight);
    const data=await measure(page);report.viewports.push({width,height,...data});
    expect(data.documentOverflow).toBe(0);expect(data.rootOverflow).toBe(0);expect(data.inlineStyles).toBe(0);
    for(const bubble of data.bubbles)expect(bubble.overflow).toBe(0);
    await page.screenshot({path:out+'/mainbar-'+width+'x'+height+'.png'});
    await writeFile(out+'/mainbar-'+width+'x'+height+'-aria.txt',await page.locator('body').ariaSnapshot());
  }
  await page.setViewportSize({width:1440,height:900});
  const located=await page.evaluate(async({session,run_id})=>{const {dashboard}=await import('/assets/app.js');return dashboard.locateReply({session_id:session,run_id,process_instance_id:dashboard.runtime().instance,action_id:crypto.randomUUID()});},{session:report.session,run_id:ids[1]});
  expect(located.status).toBe('applied');await expect(page.locator('#messages article.located')).toBeVisible();
  await page.screenshot({path:out+'/mainbar-located-1440x900.png'});
  report.checks.location={result:located,border:await page.locator('#messages article.located').evaluate(node=>getComputedStyle(node).borderColor),reading:await page.locator('#reading-status').textContent()};
