  await emit(streamPage,'state_patch',state(session,1,{coordinator_state:'running',active_run:run(session)}));
  await domain(streamPage,1,session,{name:'attempt.started',attempt_id:'capture-stream',model:'offline-capture',streamed:true},{attempt:'capture-stream',step:0});
  await domain(streamPage,2,session,{name:'block.started',index:0,block_type:'text'},{attempt:'capture-stream',step:0});
  await domain(streamPage,3,session,{name:'block.delta',index:0,text:'暂态过程输出：正式回复、结局和保存仍需分别核对。'},{attempt:'capture-stream',step:0});
  await expect(streamPage.locator('#messages .message-streaming')).toContainText('暂态过程输出');
  report.checks.streaming=await streamPage.locator('#messages .message-streaming .message-bubble').evaluate(node=>({text:node.textContent,borderStyle:getComputedStyle(node).borderStyle}));
  expect(report.checks.streaming.borderStyle).toBe('dashed');
  await streamPage.screenshot({path:out+'/mainbar-streaming-1440x900.png'});await streamPage.close();
  const reference=await context.newPage();report.referenceNetwork=[];
  reference.on('response',response=>{if(response.url().startsWith('https://unpkg.com/'))report.referenceNetwork.push({url:response.url(),status:response.status()});});
  reference.on('pageerror',error=>report.errors.push({kind:'reference-pageerror',message:String(error)}));
  await reference.goto(pathToFileURL(process.cwd()+'/docs/design/issue-122/reference/Syrup Dashboard.dc.html').href);
  await reference.getByText('CHAT',{exact:true}).waitFor();
  await writeFile(out+'/reference-initial-aria.txt',await reference.locator('body').ariaSnapshot());
  const overview=reference.getByRole('link',{name:/^Overview/});report.referenceAccessibleName=await overview.innerText();await overview.click();
  for(const [width,height] of [[1440,900],[1280,800],[390,844],[320,800]]){
    await reference.setViewportSize({width,height});await expect(reference.getByRole('heading',{name:'Overview',exact:true})).toBeAttached();
    report.reference.push({width,height,...await measure(reference,true)});
    await reference.screenshot({path:out+'/reference-overview-'+width+'x'+height+'.png'});
    await writeFile(out+'/reference-overview-'+width+'x'+height+'-aria.txt',await reference.locator('body').ariaSnapshot());
  }
  report.sourceSha256={};
  for(const file of ['src/agent_alfred/ops/static/app.js','src/agent_alfred/ops/static/app.css','src/agent_alfred/ops/static/index.html','docs/design/issue-122/reference/Syrup Dashboard.dc.html','docs/design/issue-122/reference/support.js'])report.sourceSha256[file]=createHash('sha256').update(await readFile(file)).digest('hex');
